using NSubstitute;
using NSubstitute.ExceptionExtensions;

namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly IPaymentProvider _provider;
    private readonly PaymentGateway _gateway;

    public PaymentGatewayTests()
    {
        _provider = Substitute.For<IPaymentProvider>();
        _gateway = new PaymentGateway(_provider);
    }

    #region Constructor

    [TestMethod]
    public void Constructor_NullProvider_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => new PaymentGateway(null!));
        Assert.AreEqual("provider", ex.ParamName);
    }

    #endregion

    #region ChargeAsync – validation

    [TestMethod]
    public async Task ChargeAsync_NullToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(null!, 10m));
    }

    [TestMethod]
    public async Task ChargeAsync_EmptyToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync("", 10m));
    }

    [TestMethod]
    public async Task ChargeAsync_WhitespaceToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync("   ", 10m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-100.50)]
    public async Task ChargeAsync_NonPositiveAmount_ThrowsArgumentOutOfRange(double amount)
    {
        await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", (decimal)amount));
    }

    [TestMethod]
    public async Task ChargeAsync_ExceedsMaximum_ThrowsArgumentOutOfRange()
    {
        await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", 1_000_000m));
    }

    #endregion

    #region ChargeAsync – success / failure

    [TestMethod]
    public async Task ChargeAsync_ValidRequest_ReturnsSuccessResult()
    {
        var expected = new ChargeResult("ch_123", true);
        _provider.ProcessChargeAsync("tok_abc", 49.99m, Arg.Any<CancellationToken>())
                 .Returns(expected);

        var result = await _gateway.ChargeAsync("tok_abc", 49.99m);

        Assert.AreEqual(expected.ChargeId, result.ChargeId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_ProviderDeclines_ReturnsFailureResult()
    {
        var expected = new ChargeResult("ch_456", false);
        _provider.ProcessChargeAsync("tok_bad", 100m, Arg.Any<CancellationToken>())
                 .Returns(expected);

        var result = await _gateway.ChargeAsync("tok_bad", 100m);

        Assert.AreEqual("ch_456", result.ChargeId);
        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_ProviderThrows_PropagatesException()
    {
        _provider.ProcessChargeAsync(Arg.Any<string>(), Arg.Any<decimal>(), Arg.Any<CancellationToken>())
                 .ThrowsAsync<InvalidOperationException>();

        await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.ChargeAsync("tok_any", 10m));
    }

    [TestMethod]
    [DataRow(0.01)]
    [DataRow(999999.99)]
    public async Task ChargeAsync_BoundaryAmounts_Succeeds(double amount)
    {
        var decimalAmount = (decimal)amount;
        _provider.ProcessChargeAsync("tok_ok", decimalAmount, Arg.Any<CancellationToken>())
                 .Returns(new ChargeResult("ch_boundary", true));

        var result = await _gateway.ChargeAsync("tok_ok", decimalAmount);

        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_PassesCancellationToken()
    {
        using var cts = new CancellationTokenSource();
        _provider.ProcessChargeAsync("tok_x", 5m, cts.Token)
                 .Returns(new ChargeResult("ch_ct", true));

        var result = await _gateway.ChargeAsync("tok_x", 5m, cts.Token);

        Assert.IsTrue(result.Success);
        await _provider.Received(1).ProcessChargeAsync("tok_x", 5m, cts.Token);
    }

    #endregion

    #region RefundAsync – validation

    [TestMethod]
    public async Task RefundAsync_NullChargeId_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(null!));
    }

    [TestMethod]
    public async Task RefundAsync_EmptyChargeId_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(""));
    }

    #endregion

    #region RefundAsync – success / failure

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessResult()
    {
        var expected = new RefundResult("re_789", true);
        _provider.ProcessRefundAsync("ch_123", Arg.Any<CancellationToken>())
                 .Returns(expected);

        var result = await _gateway.RefundAsync("ch_123");

        Assert.AreEqual("re_789", result.RefundId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task RefundAsync_ProviderDeclines_ReturnsFailureResult()
    {
        _provider.ProcessRefundAsync("ch_notfound", Arg.Any<CancellationToken>())
                 .Returns(new RefundResult("re_fail", false));

        var result = await _gateway.RefundAsync("ch_notfound");

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task RefundAsync_ProviderThrows_PropagatesException()
    {
        _provider.ProcessRefundAsync(Arg.Any<string>(), Arg.Any<CancellationToken>())
                 .ThrowsAsync<TimeoutException>();

        await Assert.ThrowsExactlyAsync<TimeoutException>(
            async () => await _gateway.RefundAsync("ch_timeout"));
    }

    #endregion

    #region ProcessWebhook

    [TestMethod]
    [DataRow("charge.succeeded", "Charge confirmed")]
    [DataRow("charge.failed", "Charge failed")]
    [DataRow("refund.completed", "Refund completed")]
    public void ProcessWebhook_KnownEvent_ReturnsProcessed(string eventType, string expectedMessage)
    {
        var result = _gateway.ProcessWebhook(eventType, "{\"id\":\"evt_1\"}");

        Assert.AreEqual(WebhookStatus.Processed, result.Status);
        Assert.AreEqual(expectedMessage, result.Message);
    }

    [TestMethod]
    public void ProcessWebhook_UnknownEvent_ReturnsIgnored()
    {
        var result = _gateway.ProcessWebhook("unknown.event", "{}");

        Assert.AreEqual(WebhookStatus.Ignored, result.Status);
        Assert.Contains("Unknown event", result.Message);
    }

    [TestMethod]
    public void ProcessWebhook_NullEventType_ThrowsArgumentException()
    {
        Assert.ThrowsExactly<ArgumentException>(
            () => _gateway.ProcessWebhook(null!, "{}"));
    }

    [TestMethod]
    public void ProcessWebhook_NullPayload_ThrowsArgumentException()
    {
        Assert.ThrowsExactly<ArgumentException>(
            () => _gateway.ProcessWebhook("charge.succeeded", null!));
    }

    [TestMethod]
    public void ProcessWebhook_EmptyPayload_ThrowsArgumentException()
    {
        Assert.ThrowsExactly<ArgumentException>(
            () => _gateway.ProcessWebhook("charge.succeeded", ""));
    }

    #endregion
}

